        HStack {
            VStack(alignment: .leading) {
                Text(setting.title)
                    .lineLimit(1)
                if let subtitle = value.subtitle {
                    Text(NSLocalizedString(subtitle))
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }
            }
            .opacity(disabled ? disabledOpacity : 1)
            .padding(.vertical, {
                if #available(iOS 26.0, *) {
                    0
                } else if value.subtitle != nil {
                    2
                } else {
                    0
                }
            }())

            Spacer()

            Toggle(isOn: $toggleValue) {
                EmptyView()
            }
            .labelsHidden()
            .onChange(of: toggleValue) { newValue in
                guard !disabled else { return }
                if (value.authToDisable ?? false) && !newValue {
                    Task {
                        let success = await auth()
                        if success {
                            SettingsStore.shared.set(key: key(setting.key), value: false)
                        } else {
                            toggleValue = true
                        }
                    }
                } else {
                    SettingsStore.shared.set(key: key(setting.key), value: newValue)
                }
            }
        }
        .disabled(disabled)
    }
}

