@testable import Aidoku
import Foundation
import Testing

struct LargeDownloadConfirmationTests {
    private let key = AppSettings.downloads.confirmLargeDownloads.key

    private func withDefaults(_ body: (UserDefaults) -> Void) {
        let name = "LargeDownloadConfirmationTests.\(UUID().uuidString)"
        let defaults = UserDefaults(suiteName: name)!
        defer { defaults.removePersistentDomain(forName: name) }
        body(defaults)
    }

    @Test func requiresConfirmationAboveThresholdWhenOn() {
        withDefaults { defaults in
            defaults.set(true, forKey: key)
            #expect(LargeDownloadConfirmation.isRequired(chapterCount: 51, defaults: defaults))
        }
    }

    @Test func skipsConfirmationAtThreshold() {
        withDefaults { defaults in
            defaults.set(true, forKey: key)
            #expect(!LargeDownloadConfirmation.isRequired(chapterCount: 50, defaults: defaults))
        }
    }

    @Test func skipsConfirmationWhenOff() {
        withDefaults { defaults in
            defaults.set(false, forKey: key)
            #expect(!LargeDownloadConfirmation.isRequired(chapterCount: 51, defaults: defaults))
        }
    }

    @Test func skipsConfirmationWhenNeverStored() {
        withDefaults { defaults in
            #expect(!LargeDownloadConfirmation.isRequired(chapterCount: 51, defaults: defaults))
        }
    }
}
